	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void firstTermQueryAfterDictionaryGrowthReplaysCompleteUnobservedSnapshot(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(64L * 1024 * 1024)
				.setValueDBSize(1024L * 1024)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true));
		SailRepository repository = new SailRepository(store);
		IRI claims = VF.createIRI("urn:late-term:claims");
		TripleTerm first = VF.createTripleTerm(VF.createIRI("urn:late-term:first"), PREDICATE,
				VF.createLiteral("first"));
		TripleTerm second = VF.createTripleTerm(VF.createIRI("urn:late-term:second"), PREDICATE,
				VF.createLiteral("second"));
		repository.init();
		try {
			try (RepositoryConnection writer = repository.getConnection()) {
				writer.add(VF.createIRI("urn:late-term:owner:first"), claims, first);
			}
			long originalTripleMap = mapSize(tripleStoreOf(store));
			long originalValueMap = mapSize(valueStoreOf(store));
			try (RepositoryConnection reader = repository.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				try (TupleQueryResult earlier = reader.prepareTupleQuery("SELECT ?owner WHERE { ?owner <"
						+ claims.stringValue() + "> ?term }").evaluate()) {
					LmdbStoreConnection readerConnection = (LmdbStoreConnection) ((SailRepositoryConnection) reader)
							.getSailConnection();
					assertFalse(snapshotReadViewLeases(readerConnection).isEmpty(),
							"an unobserved ordinary query must pin the pre-growth dictionary and TripleStore views");
					try (RepositoryConnection writer = repository.getConnection()) {
						writer.begin(IsolationLevels.SNAPSHOT);
						writer.add(VF.createIRI("urn:late-term:demand"), PREDICATE,
								VF.createLiteral("x".repeat(2 * 1024 * 1024)));
						writer.add(VF.createIRI("urn:late-term:owner:second"), claims, second);
						writer.commit();
					}
					assertEquals(originalTripleMap, mapSize(tripleStoreOf(store)));
					assertTrue(mapSize(valueStoreOf(store)) > originalValueMap);
					assertEquals(0, store.getBackingStore().growthMetricsSnapshot().replayRequests(),
							"the old ordinary read view must survive without an eager query replay");
					Set<Value> subjects = new HashSet<>();
					try (TupleQueryResult result = reader.prepareTupleQuery("SELECT ?s WHERE { ?owner <"
							+ claims.stringValue() + "> <<(?s <" + PREDICATE.stringValue() + "> ?o)>> }").evaluate()) {
						while (result.hasNext()) {
							subjects.add(result.next().getValue("s"));
						}
					}
					assertEquals(Set.of(first.getSubject(), second.getSubject()), subjects,
							"a late dictionary term conflict must replay the complete query and its TripleStore snapshot");
					assertTrue(store.getBackingStore().growthMetricsSnapshot().replayAccepted() > 0);
					Set<Value> owners = new HashSet<>();
					while (earlier.hasNext()) {
						owners.add(earlier.next().getValue("owner"));
					}
					assertEquals(
							Set.of(VF.createIRI("urn:late-term:owner:first"),
									VF.createIRI("urn:late-term:owner:second")),
							owners,
							"a late term conflict must also replay an earlier unobserved query from the same attempt");
					reader.commit();
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void closedValueSnapshotIsNotAnIsolationConflict(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir);
		store.init();
		ValueStore valueStore = valueStoreOf(store);
		try {
			ValueStore.ReadSnapshot snapshot;
			try (ValueStore.ReadSnapshotReservation reservation = valueStore.reserveReadSnapshot()) {
				snapshot = reservation.start();
			}
			snapshot.close();
			IOException failure = assertThrows(IOException.class, snapshot::ensureValid);
			assertFalse(failure.getMessage().contains("invalidated"),
					"a closed snapshot is distinct from a transaction invalidated by map growth");
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void pairedAdmissionWaitsOutsidePublicationAndRecursiveResolutionReusesItsView(@TempDir File dataDir)
			throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setForceSync(true));
		store.init();
		LmdbSailStore backingStore = store.getBackingStore();
		TripleStore tripleStore = tripleStoreOf(store);
		ValueStore valueStore = valueStoreOf(store);
		TxnManager tripleManager = tripleStore.getTxnManager();
		TxnManager valueManager = valueStore.getTxnManager();
		List<TxnManager.Txn> heldValueReaders = new ArrayList<>();
		ExecutorService executor = Executors.newFixedThreadPool(3);
		CountDownLatch priorityReaderStarted = new CountDownLatch(1);
		CountDownLatch releasePriorityReader = new CountDownLatch(1);
		SailDataset admittedDataset = null;
		IRI seedSubject = VF.createIRI("urn:snapshot-lifetime:capacity:seed");
		IRI innerSubject = VF.createIRI("urn:snapshot-lifetime:capacity:inner");
		TripleTerm inner = VF.createTripleTerm(innerSubject, PREDICATE, VF.createLiteral("nested under capacity"));
		TripleTerm outer = VF.createTripleTerm(seedSubject, PREDICATE, inner);
		IRI laterSubject = VF.createIRI("urn:snapshot-lifetime:capacity:later");
		Literal laterLiteral = VF.createLiteral("nested after older readers",
				VF.createIRI("urn:snapshot-lifetime:capacity:later-datatype"));
		TripleTerm laterInner = VF.createTripleTerm(laterSubject, PREDICATE, laterLiteral);
		TripleTerm laterOuter = VF.createTripleTerm(laterSubject, PREDICATE, laterInner);
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(seedSubject, PREDICATE, outer);
				writer.commit();
			}

			int triplePermits = availableReaderPermits(tripleManager);
			int valuePermits = availableReaderPermits(valueManager);
			for (int i = 0; i < valuePermits; i++) {
				heldValueReaders.add(valueManager.createReadTxn());
			}
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				sink.approve(laterSubject, PREDICATE, laterOuter, null);
				sink.flush();
			}
			Future<Void> priorityHolder = executor.submit(() -> valueManager.doWithPriority((stack, txn) -> {
				priorityReaderStarted.countDown();
				await(releasePriorityReader);
				return null;
			}));
			assertTrue(priorityReaderStarted.await(5, TimeUnit.SECONDS),
					"the reserved ValueStore reader slot must be held during the saturation case");

			Future<SailDataset> pendingAdmission = executor.submit(() -> backingStore.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ));
			awaitAvailableReaderPermits(tripleManager, triplePermits - 1);
			assertFalse(pendingAdmission.isDone(),
					"paired admission must wait for ValueStore capacity after reserving its TripleStore slot");

			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				sink.setNamespace("capacity", "urn:snapshot-lifetime:capacity:published:");
				sink.flush();
			}
			heldValueReaders.remove(heldValueReaders.size() - 1).close();
			admittedDataset = pendingAdmission.get(5, TimeUnit.SECONDS);
			assertEquals("urn:snapshot-lifetime:capacity:published:", admittedDataset.getNamespace("capacity"),
					"the admission retry must capture namespace publication completed while it waited for capacity");
			SailDataset datasetForRead = admittedDataset;
			Future<Statement> nestedRead = executor.submit(() -> {
				try (CloseableIteration<? extends Statement> statements = datasetForRead.getStatements(laterSubject,
						PREDICATE, null)) {
					assertTrue(statements.hasNext(),
							"the admitted dictionary must include IDs published after the older saturated readers opened");
					Statement result = statements.next();
					assertFalse(statements.hasNext());
					return result;
				}
			});
			try {
				Statement escaped = nestedRead.get(5, TimeUnit.SECONDS);
				Future<String> applicationRead = executor.submit(() -> {
					TripleTerm result = (TripleTerm) escaped.getObject();
					return ((Literal) ((TripleTerm) result.getObject()).getObject()).getLabel();
				});
				assertEquals("nested after older readers", applicationRead.get(5, TimeUnit.SECONDS),
						"application code must initialize escaped nested values without another dictionary reader slot");
			} catch (TimeoutException timeout) {
				throw new AssertionError("recursive lookup waited for an additional ValueStore reader", timeout);
			}
			datasetForRead.close();
			admittedDataset = null;
			releasePriorityReader.countDown();
			priorityHolder.get(5, TimeUnit.SECONDS);
		} finally {
			releasePriorityReader.countDown();
			if (admittedDataset != null) {
				admittedDataset.close();
			}
			heldValueReaders.forEach(TxnManager.Txn::close);
			executor.shutdownNow();
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void dictionaryGrowthKeepsObservedSnapshotAndDeferredValues(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(64L * 1024L * 1024L)
				.setValueDBSize(1024L * 1024L)
				.setMapGrowthReadDrainTimeoutMillis(100)
				.setAutoGrow(true));
		IRI subject = VF.createIRI("urn:dictionary-growth:original:subject");
		IRI secondSubject = VF.createIRI("urn:dictionary-growth:original:second");
		IRI context = VF.createIRI("urn:dictionary-growth:original:context");
		IRI datatype = VF.createIRI("urn:dictionary-growth:datatype:custom");
		Literal literal = VF.createLiteral("original typed value", datatype);
		TripleTerm inner = VF.createTripleTerm(subject, PREDICATE, literal);
		TripleTerm outer = VF.createTripleTerm(subject, PREDICATE, inner);
		TripleTerm laterTerm = VF.createTripleTerm(secondSubject, PREDICATE, VF.createLiteral("later term"));
		store.init();
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, outer, context);
				writer.addStatement(secondSubject, PREDICATE, literal, context);
				writer.commit();
			}
			TripleStore tripleStore = tripleStoreOf(store);
			ValueStore valueStore = valueStoreOf(store);
			long originalTripleMap = mapSize(tripleStore);
			long originalValueMap = mapSize(valueStore);
			Statement escaped;
			try (SailDataset reader = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				try (CloseableIteration<? extends Statement> observed = reader.getStatements(subject, PREDICATE,
						outer, context)) {
					assertTrue(observed.hasNext());
					escaped = observed.next();
				}
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.removeStatements(null, PREDICATE, null, context);
					writer.commit();
				}
				assertTrue(store.getBackingStore().hasRetiredValueIds(),
						"the old TripleStore reader must preserve raw IDs before values are constructed");
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.addStatement(VF.createIRI("urn:dictionary-growth:new:large"), PREDICATE,
							VF.createLiteral("g".repeat(2 * 1024 * 1024)));
					writer.addStatement(VF.createIRI("urn:dictionary-growth:new:term"), PREDICATE, laterTerm);
					writer.commit();
				}
				assertEquals(originalTripleMap, mapSize(tripleStore), "only the dictionary map must grow");
				assertTrue(mapSize(valueStore) > originalValueMap, "the oversized value must grow ValueStore");
				MapGrowthMetrics.Snapshot metrics = store.getBackingStore().growthMetricsSnapshot();
				assertEquals(0L, metrics.forcedInvalidatedViews(),
						"dictionary remapping must preserve already-observed TripleStore snapshots");
				assertEquals(0L, metrics.replayRequests(), "dictionary remapping must not replay queries");
				try (CloseableIteration<? extends Statement> deferred = reader.getStatements(secondSubject, PREDICATE,
						literal, context)) {
					assertTrue(deferred.hasNext(), "a value not constructed before resize must still match its old ID");
					assertEquals(literal, deferred.next().getObject());
					assertFalse(deferred.hasNext());
				}
				LmdbSailStore.MapResizeConflictException termConflict = assertThrows(
						LmdbSailStore.MapResizeConflictException.class,
						() -> reader.getTriples(null, null, null),
						"a first term scan after remapping must reject its unavailable original dictionary membership");
				assertEquals(LmdbSailStore.MapResizeKind.VALUE_STORE, termConflict.kind());
			}
			assertEquals(subject, escaped.getSubject());
			assertEquals(outer, escaped.getObject(), "escaped nested lazy values must retain their ID meanings");
			assertEquals(context, escaped.getContext());
		} finally {
			store.shutDown();
		}
	}

	@Test
	void retirementWaitsForOldestPinnedReaderThenDrainsAfterClose(@TempDir File dataDir) throws Exception {
		// Keep this test independent of resize fallback. The small-map test below covers forced invalidation.
		long mapSize = 64L * 1024 * 1024;
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(mapSize)
				.setValueDBSize(mapSize));
		IRI subject = VF.createIRI("urn:snapshot-lifetime:retired-subject");
		IRI context = VF.createIRI("urn:snapshot-lifetime:retired-context");
		Value object = VF.createLiteral("retired value");
		long originalId;

		store.init();
		TripleStore tripleStore = tripleStoreOf(store);
		ValueStore valueStore = valueStoreOf(store);
		long initialTripleMapSize = mapSize(tripleStore);
		long initialValueMapSize = mapSize(valueStore);
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, object, context);
				writer.commit();
			}

			SailDataset pinnedReader = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ);
			try {
				try (CloseableIteration<? extends Statement> statements = pinnedReader.getStatements(subject, PREDICATE,
						object, context)) {
					assertTrue(statements.hasNext());
					originalId = ((LmdbValue) statements.next().getSubject()).getInternalID();
				}
				assertNotEquals(LmdbValue.UNKNOWN_ID, originalId);

				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.removeStatements(subject, PREDICATE, object, context);
					writer.commit();
				}
				long dataRevisionBeforeNamespace = tripleStore.getDataRevision();
				long tripleTxnIdBeforeNamespace = lastTxnId(tripleStore.env);
				long valueTxnIdBeforeNamespace = lastTxnId(envOf(valueStore));
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.setNamespace("retirement", "urn:snapshot-lifetime:retirement:");
					writer.commit();
				}
				assertEquals(tripleTxnIdBeforeNamespace + 1, lastTxnId(tripleStore.env),
						"namespace metadata must publish atomically in the authoritative TripleStore environment");
				assertEquals(dataRevisionBeforeNamespace, tripleStore.getDataRevision(),
						"a namespace-only commit must not advance the RDF data revision");
				assertEquals(valueTxnIdBeforeNamespace, lastTxnId(envOf(valueStore)),
						"an ineligible namespace-only commit must not write the ValueStore environment");
				assertTrue(store.getBackingStore().hasRetiredValueIds(),
						"an older pinned reader keeps retirement ineligible across a namespace-only publication");
				assertNull(pinnedReader.getNamespace("retirement"),
						"an already-open reader keeps its captured namespace map");
				try (SailDataset afterNamespace = store.getBackingStore()
						.getExplicitSailSource()
						.dataset(IsolationLevels.READ_COMMITTED)) {
					assertEquals("urn:snapshot-lifetime:retirement:", afterNamespace.getNamespace("retirement"));
				}
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.addStatement(subject, PREDICATE, object, context);
					writer.commit();
				}
				assertTrue(store.getBackingStore().hasRetiredValueIds(),
						"retirement intents remain durable while the older TripleStore reader is pinned");
				assertEquals(originalId, readSubjectId(store, subject, object, context),
						"the active older reader must keep the dictionary ID from being retired and reused");
			} finally {
				pinnedReader.close();
			}

			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.removeStatements(subject, PREDICATE, object, context);
				writer.commit();
			}
			long oldestPinnedRevision = tripleStore.getTxnManager().minPinnedSnapshotRevision();
			assertTrue(oldestPinnedRevision == Long.MAX_VALUE || oldestPinnedRevision >= tripleStore.getDataRevision(),
					"all remaining readers must be at or beyond the removal generation before reclamation");
			assertFalse(store.getBackingStore().hasRetiredValueIds(),
					"the deleting connection's detached snapshot must not pin IDs beyond publication");
			long tripleTxnIdBeforeEmpty = lastTxnId(tripleStore.env);
			long valueTxnIdBeforeEmpty = lastTxnId(envOf(valueStore));
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.commit();
			}
			assertEquals(tripleTxnIdBeforeEmpty, lastTxnId(tripleStore.env),
					"an empty transaction must not commit the TripleStore environment");
			assertEquals(valueTxnIdBeforeEmpty, lastTxnId(envOf(valueStore)),
					"an empty transaction must not commit the ValueStore environment");
			assertFalse(store.getBackingStore().hasRetiredValueIds(),
					"retirement was drained when the deleting writer retired its detached snapshot");
			long dataRevisionBeforeEligibleNamespace = tripleStore.getDataRevision();
			long tripleTxnIdBeforeEligibleNamespace = lastTxnId(tripleStore.env);
			long valueTxnIdBeforeEligibleNamespace = lastTxnId(envOf(valueStore));
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.setNamespace("retirement-eligible", "urn:snapshot-lifetime:retirement-eligible:");
				writer.commit();
			}
			assertEquals(tripleTxnIdBeforeEligibleNamespace + 1, lastTxnId(tripleStore.env),
					"an eligible namespace-only commit must publish its authoritative namespace snapshot");
			assertEquals(dataRevisionBeforeEligibleNamespace, tripleStore.getDataRevision(),
					"an eligible namespace-only commit must not advance the RDF data revision");
			assertEquals(valueTxnIdBeforeEligibleNamespace, lastTxnId(envOf(valueStore)),
					"an eligible namespace-only commit must not write the ValueStore environment");
			assertFalse(store.getBackingStore().hasRetiredValueIds(),
					"namespace-only publication does not recreate already-drained retirement intents");
			IRI maintenanceSubject = VF.createIRI("urn:snapshot-lifetime:maintenance-subject");
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(maintenanceSubject, PREDICATE, VF.createLiteral("maintenance"));
				writer.commit();
			}
			assertFalse(store.getBackingStore().hasRetiredValueIds(),
					"a later TripleStore publication drains eligible retirement intents");
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, object, context);
				writer.commit();
			}
			assertNotEquals(originalId, readSubjectId(store, subject, object, context),
					"after the last older reader closes, its retirement intent must be reclaimed");
			assertEquals(initialTripleMapSize, mapSize(tripleStore),
					"the retirement lifecycle test must not resize the TripleStore map");
			assertEquals(initialValueMapSize, mapSize(valueStore),
					"the retirement lifecycle test must not resize the ValueStore map");
			assertEquals(0, store.getBackingStore().growthMetricsSnapshot().growthEpisodes(),
					"the retirement lifecycle test must not enter map-growth coordination");
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void firstTermDemandDuringDictionaryQuiescenceKeepsReplayToken(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setMapGrowthReadDrainTimeoutMillis(5_000));
		store.init();
		LmdbSailStore backing = store.getBackingStore();
		CountDownLatch notificationsCaptured = new CountDownLatch(1);
		CountDownLatch releaseNotification = new CountDownLatch(1);
		AtomicReference<LmdbSailStore.MapGrowthToken> ordinaryReplayToken = new AtomicReference<>();
		LmdbSailStore.MapGrowthObserver ordinaryObserver = (kind, token, deadline, attempts, views) -> {
			ordinaryReplayToken.set(token);
			return false;
		};
		LmdbSailStore.MapGrowthObserver termObserver = (kind, token, deadline, attempts, views) -> {
			notificationsCaptured.countDown();
			try {
				assertTrue(releaseNotification.await(10, TimeUnit.SECONDS));
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
			}
			return false;
		};
		ExecutorService executor = Executors.newSingleThreadExecutor();
		try (LmdbSailStore.ReadAttemptLease ordinaryAttempt = backing.registerReadAttempt(ordinaryObserver);
				LmdbSailStore.ReadAttemptLease termAttempt = backing.registerReadAttempt(termObserver);
				LmdbSailStore.ReadView ordinaryView = backing.createTransactionReadView(ordinaryObserver,
						ordinaryAttempt);
				LmdbSailStore.ReadView termView = backing.createTransactionReadView(termObserver, termAttempt);
				LmdbSailStore.MapGrowthAttempt growth = backing.beginMapGrowthAttempt(new Object())) {
			termView.requireDictionaryTermSnapshot();
			Future<?> quiescence = executor.submit(() -> {
				growth.requestQuiescence(LmdbSailStore.MapResizeKind.VALUE_STORE);
				return null;
			});
			try {
				assertTrue(notificationsCaptured.await(10, TimeUnit.SECONDS));
				assertNull(ordinaryReplayToken.get(), "ordinary reads must receive no eager dictionary replay");
				LmdbSailStore.MapResizeConflictException conflict = assertThrows(
						LmdbSailStore.MapResizeConflictException.class, ordinaryView::requireDictionaryTermSnapshot,
						"new term membership demand after notification capture must classify its complete attempt");
				assertEquals(LmdbSailStore.MapResizeKind.VALUE_STORE, conflict.kind());
				assertSame(growth.token(), ordinaryReplayToken.get());
			} finally {
				ordinaryView.retireNativeSnapshots(LmdbSailStore.MapResizeKind.VALUE_STORE);
				termView.retireNativeSnapshots(LmdbSailStore.MapResizeKind.VALUE_STORE);
				releaseNotification.countDown();
				quiescence.get(10, TimeUnit.SECONDS);
			}
		} finally {
			releaseNotification.countDown();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(10, TimeUnit.SECONDS));
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void activeTermIteratorReportsDictionaryResizeConflict(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(64L * 1024 * 1024)
				.setValueDBSize(1024L * 1024)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true));
		IRI subject = VF.createIRI("urn:active-term:owner");
		TripleTerm first = VF.createTripleTerm(VF.createIRI("urn:active-term:first"), PREDICATE,
				VF.createLiteral("first term"));
		TripleTerm second = VF.createTripleTerm(VF.createIRI("urn:active-term:second"), PREDICATE,
				VF.createLiteral("second term"));
		store.init();
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, first);
				writer.addStatement(subject, PREDICATE, second);
				writer.commit();
			}
			long initialTripleMapSize = mapSize(tripleStoreOf(store));
			long initialValueMapSize = mapSize(valueStoreOf(store));
			try (SailDataset reader = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ);
					CloseableIteration<? extends TripleTerm> terms = reader.getTriples(null, PREDICATE, null)) {
				assertTrue(terms.hasNext());
				TripleTerm escaped = terms.next();
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.addStatement(subject, PREDICATE, VF.createLiteral("x".repeat(2 * 1024 * 1024)));
					writer.commit();
				}
				assertEquals(initialTripleMapSize, mapSize(tripleStoreOf(store)));
				assertTrue(mapSize(valueStoreOf(store)) > initialValueMapSize);
				assertTrue(store.getBackingStore().growthMetricsSnapshot().forcedInvalidatedViews() > 0,
						"an active dictionary term cursor must keep the strict relational growth boundary");
				LmdbSailStore.MapResizeConflictException conflict = assertThrows(
						LmdbSailStore.MapResizeConflictException.class, terms::hasNext);
				assertEquals(LmdbSailStore.MapResizeKind.VALUE_STORE, conflict.kind());
				assertTrue(escaped.equals(first) || escaped.equals(second),
						"a term returned before invalidation must retain its original value");
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void directTermDatasetReportsForcedResizeConflictAndRetiresAfterClose(@TempDir File dataDir) throws Exception {
		long tripleMapSize = 64L * 1024 * 1024;
		long smallValueMapSize = 1024L * 1024;
		long drainTimeoutMillis = 1_000;
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(tripleMapSize)
				.setValueDBSize(smallValueMapSize)
				.setMapGrowthReadDrainTimeoutMillis(drainTimeoutMillis)
				.setAutoGrow(true));
		IRI subject = VF.createIRI("urn:snapshot-lifetime:forced-reader:subject");
		IRI context = VF.createIRI("urn:snapshot-lifetime:forced-reader:context");
		IRI growthPredicate = VF.createIRI("urn:snapshot-lifetime:forced-reader:growth-predicate");
		Value object = VF.createLiteral("retired value");
		Resource escapedSubject;
		long originalId;

		store.init();
		TripleStore tripleStore = tripleStoreOf(store);
		ValueStore valueStore = valueStoreOf(store);
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, object, context);
				writer.commit();
			}
			long initialTripleMapSize = mapSize(tripleStore);
			long initialValueMapSize = mapSize(valueStore);
			long initialValueOccupiedBytes = valueStore.occupiedBytes();

			SailDataset pinnedReader = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ);
			try {
				try (CloseableIteration<? extends TripleTerm> terms = pinnedReader.getTriples(null, null, null)) {
					assertFalse(terms.hasNext(), "observed empty term membership still belongs to this snapshot");
				}
				try (CloseableIteration<? extends Statement> statements = pinnedReader.getStatements(subject, PREDICATE,
						object, context)) {
					assertTrue(statements.hasNext(), "the direct dataset must have consumed a real old-generation row");
					Statement returned = statements.next();
					escapedSubject = returned.getSubject();
					originalId = ((LmdbValue) escapedSubject).getInternalID();
				}
				assertNotEquals(LmdbValue.UNKNOWN_ID, originalId);

				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					writer.removeStatements(subject, PREDICATE, object, context);
					writer.commit();
				}
				assertTrue(store.getBackingStore().hasRetiredValueIds(),
						"the consumed old-generation reader must initially protect retired dictionary IDs");

				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					for (int i = 0; i < 5_000; i++) {
						writer.addStatement(VF.createIRI("urn:snapshot-lifetime:forced-reader:" + i), growthPredicate,
								VF.createLiteral("g".repeat(512) + i));
					}
					writer.commit();
				}
				assertEquals(initialTripleMapSize, mapSize(tripleStore),
						"the large TripleStore map isolates this forced episode to ValueStore growth");
				assertTrue(mapSize(valueStore) > initialValueMapSize,
						"the buffered unique values must grow the small ValueStore map");
				MapGrowthMetrics.Snapshot metrics = store.getBackingStore().growthMetricsSnapshot();
				assertTrue(metrics.forcedInvalidationEpisodes() > 0,
						"the short drain deadline must exercise the bounded reader-invalidation fallback");
				assertTrue(metrics.forcedInvalidatedViews() > 0,
						"the direct dataset's old native view must be included in the forced invalidation");
				long oldestTripleRevision = tripleStore.getTxnManager().minPinnedSnapshotRevision();
				assertTrue(
						oldestTripleRevision == Long.MAX_VALUE || oldestTripleRevision >= tripleStore.getDataRevision(),
						"forced paired-view retirement must release the old TripleStore pin while keeping the logical handle open");
				long oldestValueRevision = valueStore.getTxnManager().minPinnedSnapshotRevision();
				assertTrue(
						oldestValueRevision == Long.MAX_VALUE || oldestValueRevision >= tripleStore.getDataRevision(),
						"forced paired-view retirement must release the old ValueStore pin while keeping the logical handle open");
				assertEquals(subject.stringValue(), escapedSubject.stringValue(),
						"values returned before retirement must remain usable after normal value materialization");

				LmdbSailStore.MapResizeConflictException conflict = assertThrows(
						LmdbSailStore.MapResizeConflictException.class,
						() -> pinnedReader.getNamespace("retirement"),
						"an already-observed direct dataset cannot read through a remapped ValueStore view");
				assertEquals(LmdbSailStore.MapResizeKind.VALUE_STORE, conflict.kind());
				long valueMapAfterFirstGrowth = mapSize(valueStore);
				long valueOccupiedAfterFirstGrowth = valueStore.occupiedBytes();
				int secondGrowthCount = Math.toIntExact(valueMapAfterFirstGrowth / 512L + 1L);
				List<Statement> secondGrowthBatch = valueGrowthBatch(growthPredicate, "second", secondGrowthCount);
				assertTrue(Math.multiplyExact((long) secondGrowthBatch.size(), 512L) > valueMapAfterFirstGrowth,
						"unique 512-byte literals must exceed the entire previous map before native overhead");
				long secondGrowthStarted = System.nanoTime();
				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					for (Statement statement : secondGrowthBatch) {
						writer.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
					}
					writer.commit();
				}
				try (SailConnection admissionBarrier = store.getConnection()) {
					admissionBarrier.begin(IsolationLevels.SNAPSHOT);
					admissionBarrier.rollback();
				}
				long valueMapAfterSecondGrowth = mapSize(valueStore);
				long valueOccupiedAfterSecondGrowth = valueStore.occupiedBytes();
				assertTrue(valueMapAfterSecondGrowth > valueMapAfterFirstGrowth,
						"the still-open invalidated dataset must overlap a second real ValueStore resize; initial map/occupied="
								+ initialValueMapSize + "/" + initialValueOccupiedBytes + ", after first="
								+ valueMapAfterFirstGrowth + "/" + valueOccupiedAfterFirstGrowth + ", after second="
								+ valueMapAfterSecondGrowth + "/" + valueOccupiedAfterSecondGrowth + ", statementCount="
								+ secondGrowthBatch.size());
				assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - secondGrowthStarted) < drainTimeoutMillis,
						"a retired native pin must not consume a second bounded drain interval");
				assertThrows(LmdbSailStore.MapResizeConflictException.class,
						() -> {
							try (CloseableIteration<? extends Statement> staleStatements = pinnedReader.getStatements(
									subject,
									PREDICATE, object, context)) {
								staleStatements.hasNext();
							}
						},
						"every later access must fail before touching the stale native generation");
			} finally {
				pinnedReader.close();
			}

			long oldestTripleRevision = tripleStore.getTxnManager().minPinnedSnapshotRevision();
			assertTrue(oldestTripleRevision == Long.MAX_VALUE || oldestTripleRevision >= tripleStore.getDataRevision(),
					"closing an invalidated dataset must release its TripleStore snapshot lease");
			long oldestValueRevision = valueStore.getTxnManager().minPinnedSnapshotRevision();
			assertTrue(oldestValueRevision == Long.MAX_VALUE || oldestValueRevision >= tripleStore.getDataRevision(),
					"closing an invalidated dataset must release its ValueStore snapshot lease");
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(VF.createIRI("urn:snapshot-lifetime:forced-reader:maintenance"), PREDICATE,
						VF.createLiteral("maintenance"));
				writer.commit();
			}
			assertFalse(store.getBackingStore().hasRetiredValueIds(),
					"after the invalidated dataset closes, a later publication must drain retired values");
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(subject, PREDICATE, object, context);
				writer.commit();
			}
			assertNotEquals(originalId, readSubjectId(store, subject, object, context),
					"reclaimed IDs must not remain attached to the old dataset's retired statement");
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void noneImportWithoutOtherReadersDoesNotUseResizeFallback(@TempDir File dataDir) throws Exception {
		long mapSize = 10L * 1024 * 1024;
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc")
				.setForceSync(true)
				.setTripleDBSize(mapSize)
				.setValueDBSize(mapSize)
				.setMapGrowthReadDrainTimeoutMillis(100)
				.setAutoGrow(true));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (SailRepositoryConnection writer = repository.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.add(BenchmarkResources.openDecompressedStream("benchmarkFiles/datagovbe-valid.ttl.gz"), "",
						RDFFormat.TURTLE);
				writer.commit();
			}
			MapGrowthMetrics.Snapshot metrics = store.getBackingStore().growthMetricsSnapshot();
			assertTrue(metrics.tripleStoreResizes() > 0,
					"the import must exercise real TripleStore map growth");
			assertTrue(metrics.valueStoreResizes() > 0,
					"the import must exercise real ValueStore map growth");
			assertEquals(0, metrics.forcedInvalidationEpisodes(),
					"an import with no independent reader must not fall back to reader invalidation");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void statementIteratorFailsAfterTripleStoreMapGrowth(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(TRIPLE_STORE_GROWTH_MAP_SIZE)
				.setMapGrowthThreshold(TRIPLE_STORE_GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(0)
				.setAutoGrow(true);
		LmdbStore store = new LmdbStore(dataDir, config);
		IRI seedSubject = VF.createIRI("urn:snapshot-lifetime:resize:seed");
		TripleStore tripleStore;
		long initialMapSize;

		store.init();
		try {
			try (SailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT);
				writer.addStatement(seedSubject, PREDICATE, VF.createLiteral("seed"));
				writer.commit();
			}
			tripleStore = tripleStoreOf(store);
			initialMapSize = mapSize(tripleStore);

			try (SailDataset reader = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ);
					CloseableIteration<? extends Statement> statements = reader.getStatements(null, null, null)) {
				assertTrue(statements.hasNext());
				assertEquals(seedSubject, statements.next().getSubject());

				try (SailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.SNAPSHOT);
					String namespace = addTripleStoreGrowthDemand(writer, initialMapSize);
					for (int i = 0; i < 10_000; i++) {
						writer.addStatement(VF.createIRI("urn:snapshot-lifetime:resize:" + i), PREDICATE,
								VF.createLiteral("value"));
					}
					writer.commit();
					awaitTripleStoreGrowth(store, tripleStore, initialMapSize, namespace);
				}

				assertTrue(mapSize(tripleStore) > initialMapSize,
						"the fixture must grow the TripleStore map while the reader is pinned");
				assertThrows(SailConflictException.class, statements::hasNext,
						"a TripleStore cursor must fail retryably instead of renewing onto a newer map generation");
			}
		} finally {
			store.shutDown();
		}
	}

